1	export type Scenario = {
2	  customer: { yearsWithMHPCO: number };
3	  steps: { op: string; items: { type: string }[] }[];
4	};
5	
6	export type ScenarioResult = {
7	  results: { premium: number }[];
8	};
9	
10	const PROCESSING_FEE = 5;
11	
12	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
13	
14	const BASE_PREMIUMS: Record<string, number> = {
15	  sword: 100,
16	  amulet: 60,
17	  staff: 80,
18	  potion: 40,
19	  rune: 25,
20	  moonstone: 25,
21	};
22	
23	// Percentages stay in integer percent points: multiply first, divide by 100
24	// last. A float multiplier such as `base * 1.1` yields 110.00000000000001 for
25	// a sword and breaks the ceil. `(base * 110) / 100` gives exactly 110.
26	const increasedBy = (amount: number, percent: number): number =>
27	  (amount * (100 + percent)) / 100;
28	
29	const quote = (items: { type: string }[]): number => {
30	  const policyBase = items.reduce(
31	    (sum, item) => sum + BASE_PREMIUMS[item.type],
32	    0,
33	  );
34	
35	  const surcharged = increasedBy(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);
36	
37	  // Rounding is in the MHPCO's favour: premiums round up.
38	  return Math.ceil(surcharged) + PROCESSING_FEE;
39	};
40	
41	export const runScenario = (scenario: Scenario): ScenarioResult => ({
42	  results: scenario.steps.map((step) => ({ premium: quote(step.items) })),
43	});
