const increasedBy = (amount: number, percent: number): number =>
  (amount * (100 + percent)) / 100;

const policyBaseOf = (items: { type: string }[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const withFirstInsuranceSurcharge = (policyBase: number): number =>
  increasedBy(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);

const quote = (items: { type: string }[]): number => {
  const surcharged = withFirstInsuranceSurcharge(policyBaseOf(items));

  // Rounding is in the MHPCO's favour: premiums round up.
  return Math.ceil(surcharged) + PROCESSING_FEE;
};
